interface Counter {
  [key: string]: number;
}

function freq(text: string): Counter {
  var out: Counter = {};
  for (var i = 0; i < text.length; i++) {
    var ch: string = text[i];
    if (out[ch] === undefined) {
      out[ch] = 1;
    } else {
      out[ch] = out[ch] + 1;
    }
  }
  return out;
}

function unique(text: string): string[] {
  var out: Counter = {};
  var list: string[] = [];
  for (var i = 0; i < text.length; i++) {
    var ch: string = text[i];
    if (out[ch] === undefined) {
      out[ch] = 1;
      list.push(ch);
    }
  }
  return list;
}

